public int randomELevel(L1ItemInstance item, int bless) {
		int level = 0;
		switch (bless) {
		case 0:// 祝福
		case 128:// 封印祝福
			if (item.getBless() < 3) {
				Random random = new Random();
				int i = random.nextInt(100) + 1;
				if (item.getEnchantLevel() <= 2) {// 強化值小於2
					if (i < 32) {
						level = 1;
					} else if ((i >= 33) && (i <= 76)) {
						level = 2;
					} else if ((i >= 77) && (i <= 100)) {
						level = 3;
					}
				} else if ((item.getEnchantLevel() >= 3) && (item.getEnchantLevel() <= 5)) {// 強化值3~5
					if (i < 50) {
						level = 2;
					} else {
						level = 1;
					}
				} else {
					level = 1;
				}
			}
			break;
		case 1:// 一般
		case 129:// 封印一般
			if (item.getBless() < 3) {
				level = 1;
			}
			break;
		case 2:// 詛咒
		case 130:// 封印詛咒
			if (item.getBless() < 3) {
				level = -1;
			}
			break;
		case 3:// 幻象
		case 131:// 封印幻象
			if (item.getBless() == 3) {
				level = 1;
			}
			break;
		}
		return level;
	}

