public void failureEnchant(L1PcInstance pc, L1ItemInstance item) {
		/** [原碼] 裝備保護卷軸 */
		if (item.getproctect() == true) {
			item.setEnchantLevel(item.getEnchantLevel() - 1);// 強化值-1
			pc.getInventory().updateItem(item, L1PcInventory.COL_ENCHANTLVL);// 更新強化值
			pc.getInventory().saveItem(item, L1PcInventory.COL_ENCHANTLVL);// 保存更新強化值
			item.setproctect(false);
			// 由於受到了魔法力量的保護，雖然產生激烈的 藍色的 光芒，但是裝備沒有消失。
			pc.sendPackets(new S_ServerMessage(1310));
			return;
		}

		StringBuilder s = new StringBuilder();

		if (ConfigRecord.LOGGING_BAN_ENCHANT) {
			LogEnchantReading.get().failureEnchant(pc, item);
		}

		if (!item.isIdentified()) {
			s.append(item.getName());
		} else {
			String pm = "";
			if (item.getEnchantLevel() > 0) {
				pm = "+";
			}
			s.append(pm + item.getEnchantLevel() + " " + item.getName());
		}

		pc.sendPackets(new S_ServerMessage(164, s.toString(), "$252"));
		/** GiveBack 衝裝贖回系統 */
		GiveBack.savepcid.add(Integer.valueOf(pc.getId()));
		GiveBack.saveweapon.add(item);
		GiveBack.savename.add(item.getNumberedViewName(1L));

		pc.getInventory().removeItem(item, item.getCount());
		//_log.info("人物:" + pc.getName() + "點爆物品(武器)" + item.getItem().getName() + " 物品OBJID:" + item.getId());
				WriteLogTxt
				.Recording("點爆武器紀錄","人物:" +"【"+ pc.getName() +"】"+ "點爆<武器>" +"【" +"+"+item.getEnchantLevel() + item.getItem().getName() +"】"+ " 物品OBJID:" + item.getId());
				}

public void failureEnchant2(L1PcInstance pc, L1ItemInstance item) {
		/** [原碼] 裝備保護卷軸 */
