		WriteLogTxt
				.Recording("工匠_名人_達人卷軸紀錄","人物:" +"【"+ pc.getName() +"】"+ "強化失敗(武器沒消失)" +"【" +"+"+item.getEnchantLevel() + item.getItem().getName() +"】"+ " 物品OBJID:" + item.getId());
