public void successEnchant(L1PcInstance pc, L1ItemInstance item, int randomELevel) {
		/** [原碼] 裝備保護卷軸 */
		if (item.getproctect() == true) {
			item.setproctect(false);
			pc.sendPackets(new S_SystemMessage("裝備保護卷軸的力量消失了。"));
		}

		StringBuilder s = new StringBuilder();
		StringBuilder sa = new StringBuilder();
		StringBuilder sb = new StringBuilder();

		if (!item.isIdentified()) {
			s.append(item.getName());
		} else {
			s.append(item.getLogName());
		}

		switch (randomELevel) {
		case 0:
			pc.sendPackets(new S_ServerMessage(160, s.toString(), "$252", "$248"));
			return;
		case -1:
			sa.append("$246");
			sb.append("$247");
			break;
		case 1:
			sa.append("$245");
			sb.append("$247");
			break;
		case 2:
		case 3:
			sa.append("$245");
			sb.append("$248");
		}

		pc.sendPackets(new S_ServerMessage(161, s.toString(), sa.toString(), sb.toString()));

		int oldEnchantLvl = item.getEnchantLevel();// 強化前的強化值
		int newEnchantLvl = oldEnchantLvl + randomELevel;// 強化後的強化值

		if (oldEnchantLvl != newEnchantLvl) {
			if (newEnchantLvl >= 9) {
				World.get().broadcastPacketToAll(new S_HelpMessage(pc.getName(),
						s.toString() + " " + sb.toString() + " " + sa.toString() + " $251"));
			}
			item.setEnchantLevel(newEnchantLvl);// 設定新的強化值
			pc.getInventory().updateItem(item, L1PcInventory.COL_ENCHANTLVL);// 更新強化值
			pc.getInventory().saveItem(item, L1PcInventory.COL_ENCHANTLVL);// 保存更新強化值

			if (randomELevel == -1) {// 詛咒武卷
				int oldAttrEnchantLvl = item.getAttrEnchantLevel();//屬性強化階段
				if (oldAttrEnchantLvl >= 1) {// 至少1階段以上
					int newAttrEnchantLvl = oldAttrEnchantLvl + randomELevel;
					// System.out.println("newAttrEnchantLvl ==" +
					// newAttrEnchantLvl);
					item.setAttrEnchantLevel(newAttrEnchantLvl);
					pc.getInventory().updateItem(item, L1PcInventory.COL_ATTR_ENCHANT_LEVEL);
					pc.getInventory().saveItem(item, L1PcInventory.COL_ATTR_ENCHANT_LEVEL);
				}
			}
		}

	}

