methods.source:
public void failureEnchant(L1PcInstance pc, L1ItemInstance item) {
		/** [原碼] 裝備保護卷軸 */
		if (item.getproctect() == true) {
			int itemid = item.getItemId();
			int oldenchantlvl = item.getEnchantLevel();// 強化前的強化值
			item.setEnchantLevel(item.getEnchantLevel() - 1);// 強化值-1
			pc.getInventory().updateItem(item, L1PcInventory.COL_ENCHANTLVL);// 更新強化值
			pc.getInventory().saveItem(item, L1PcInventory.COL_ENCHANTLVL);// 保存更新強化值

			if (item.isEquipped()) {
				pc.addAc(1);// 防禦力

				Integer mr = L1ItemPower.MR.get(Integer.valueOf(itemid));
				if (mr != null) {
					pc.addMr(-1 * mr.intValue());
				}

				Integer sp = L1ItemPower.SP.get(Integer.valueOf(itemid));
				if (sp != null) {
					if (itemid == 20107 || itemid == 120107) {// 巫妖斗篷)
						if (oldenchantlvl >= 3) {// +3開始增加魔攻
							pc.addSp(-1 * sp.intValue());
						}
					} else if (itemid == 300431) {// 法師臂甲
						switch (oldenchantlvl) {
						case 5:
						case 7:
						case 9:
							pc.addSp(-1 * sp.intValue());
							break;
						}
					} else {// 其他道具
						pc.addSp(-1 * sp.intValue());
					}
				}

				Integer hp = L1ItemPower.HP.get(Integer.valueOf(itemid));
				if (hp != null) {
					if (itemid == 300429) {// 體力臂甲
						switch (oldenchantlvl) {
						case 5:
						case 7:
						case 9:
							pc.addMaxHp(-1 * hp.intValue());
							break;
						}
					} else {// 其他道具
						pc.addMaxHp(-1 * hp.intValue());
					}
				}

				Integer hit = L1ItemPower.HIT.get(Integer.valueOf(itemid));
				if (hit != null) {
					if (itemid == 400051) {// 激怒手套
						if (oldenchantlvl >= 5) {// 加5開始增加命中率
							pc.addHitModifierByArmor(-1 * hit.intValue());
						}
					} else {// 其他道具
						pc.addHitModifierByArmor(-1 * hit.intValue());
					}
				}

				Integer dmgr = L1ItemPower.DMG_REDUCE.get(Integer.valueOf(itemid));
				if (dmgr != null) {
					if (itemid == 300430) {// 守護的臂甲
						switch (oldenchantlvl) {
						case 5:
						case 7:
						case 9:
							pc.addDamageReductionByArmor(-1 * dmgr.intValue());
							break;
						}
					} else {// 其他道具
						pc.addDamageReductionByArmor(-1 * dmgr.intValue());
					}
				}

				pc.sendPackets(new S_SPMR(pc));// 更新魔攻魔防
				pc.sendPackets(new S_OwnCharStatus(pc));// 更新人物屬性
				pc.sendPackets(new S_PacketBox(S_PacketBox.UPDATE_ER, pc.getEr()));// 迴避率更新
			}

			item.setproctect(false);
			// 由於受到了魔法力量的保護，雖然產生激烈的 藍色的 光芒，但是裝備沒有消失。
			pc.sendPackets(new S_ServerMessage(1310));
			return;
		}
		/** [原碼] 裝備保護卷軸 END */

		StringBuilder s = new StringBuilder();

		if (ConfigRecord.LOGGING_BAN_ENCHANT) {
			LogEnchantReading.get().failureEnchant(pc, item);
		}

		if (!item.isIdentified()) {
			s.append(item.getName());
		} else {
			s.append(item.getLogName());
		}

		pc.sendPackets(new S_ServerMessage(164, s.toString(), "$252"));
		/** GiveBack 衝裝贖回系統 */
		GiveBack.savepcid.add(Integer.valueOf(pc.getId()));
		GiveBack.saveweapon.add(item);
		GiveBack.savename.add(item.getNumberedViewName(1L));

		pc.getInventory().removeItem(item, item.getCount());
		//_log.info("人物:" + pc.getName() + "點爆物品" + item.getLogName() + " 物品OBJID:" + item.getId());
				WriteLogTxt
				.Recording("點爆裝備紀錄","人物:" +"【"+ pc.getName() +"】"+ "點爆<裝備>" +"【" +"+"+item.getEnchantLevel() + item.getItem().getName() + "】"+" 物品OBJID:" + item.getId());
			}

public void successEnchant(L1PcInstance pc, L1ItemInstance item, int randomELevel) {
		/** [原碼] 裝備保護卷軸 */
		if (item.getproctect() == true) {
			item.setproctect(false);
			pc.sendPackets(new S_SystemMessage("裝備保護卷軸的力量消失了。"));
		}

		StringBuilder s = new StringBuilder();
		StringBuilder sa = new StringBuilder();
		StringBuilder sb = new StringBuilder();

		if (!item.isIdentified()) {
			s.append(item.getName());
		} else if (item.getEnchantLevel() > 0) {
			s.append("+" + item.getEnchantLevel() + " " + item.getName());
		} else if (item.getEnchantLevel() < 0) {
			s.append(item.getEnchantLevel() + " " + item.getName());
		} else {
			s.append(item.getName());
		}

		switch (randomELevel) {
		case 0:
			pc.sendPackets(new S_ServerMessage(160, s.toString(), "$252", "$248"));
			return;
		case -1:
			sa.append("$246");
			sb.append("$247");
			break;
		case 1:
			sa.append("$252");
			sb.append("$247");
			break;
		case 2:
		case 3:
			sa.append("$252");
			sb.append("$248");
		}

		pc.sendPackets(new S_ServerMessage(161, s.toString(), sa.toString(), sb.toString()));

		int oldEnchantLvl = item.getEnchantLevel();// 強化前的強化值
		int newEnchantLvl = oldEnchantLvl + randomELevel;// 強化後的強化值

		item.setEnchantLevel(newEnchantLvl);// 設定新的強化值
		pc.getInventory().updateItem(item, L1PcInventory.COL_ENCHANTLVL);// 更新強化值
		pc.getInventory().saveItem(item, L1PcInventory.COL_ENCHANTLVL);// 保存更新強化值

		if (oldEnchantLvl != newEnchantLvl) {
			if (newEnchantLvl >= 9) {
				World.get().broadcastPacketToAll(new S_HelpMessage(pc.getName(),
