				if (mr != null) {
					pc.addMr(-1 * mr.intValue());
				}

				Integer sp = L1ItemPower.SP.get(Integer.valueOf(itemid));
				if (sp != null) {
					if (itemid == 20107 || itemid == 120107) {// 巫妖斗篷)
						if (oldenchantlvl >= 3) {// +3開始增加魔攻
							pc.addSp(-1 * sp.intValue());
						}
					} else if (itemid == 300431) {// 法師臂甲
						switch (oldenchantlvl) {
						case 5:
						case 7:
						case 9:
							pc.addSp(-1 * sp.intValue());
							break;
						}
					} else {// 其他道具
						pc.addSp(-1 * sp.intValue());
					}
				}

				Integer hp = L1ItemPower.HP.get(Integer.valueOf(itemid));
				if (hp != null) {
					if (itemid == 300429) {// 體力臂甲
						switch (oldenchantlvl) {
						case 5:
						case 7:
						case 9:
							pc.addMaxHp(-1 * hp.intValue());
							break;
						}
					} else {// 其他道具
						pc.addMaxHp(-1 * hp.intValue());
					}
				}

				Integer hit = L1ItemPower.HIT.get(Integer.valueOf(itemid));
				if (hit != null) {
					if (itemid == 400051) {// 激怒手套
						if (oldenchantlvl >= 5) {// 加5開始增加命中率
							pc.addHitModifierByArmor(-1 * hit.intValue());
						}
					} else {// 其他道具
						pc.addHitModifierByArmor(-1 * hit.intValue());
					}
				}

				Integer dmgr = L1ItemPower.DMG_REDUCE.get(Integer.valueOf(itemid));
				if (dmgr != null) {
					if (itemid == 300430) {// 守護的臂甲
						switch (oldenchantlvl) {
