			}

			item.setproctect(false);
			// 由於受到了魔法力量的保護，雖然產生激烈的 藍色的 光芒，但是裝備沒有消失。
			pc.sendPackets(new S_ServerMessage(1310));
			return;
		}
		/** [原碼] 裝備保護卷軸 END */

		StringBuilder s = new StringBuilder();

		if (ConfigRecord.LOGGING_BAN_ENCHANT) {
			LogEnchantReading.get().failureEnchant(pc, item);
		}

		if (!item.isIdentified()) {
			s.append(item.getName());
		} else {
			s.append(item.getLogName());
		}

		pc.sendPackets(new S_ServerMessage(164, s.toString(), "$252"));
		/** GiveBack 衝裝贖回系統 */
		GiveBack.savepcid.add(Integer.valueOf(pc.getId()));
		GiveBack.saveweapon.add(item);
		GiveBack.savename.add(item.getNumberedViewName(1L));

		pc.getInventory().removeItem(item, item.getCount());
		//_log.info("人物:" + pc.getName() + "點爆物品" + item.getLogName() + " 物品OBJID:" + item.getId());
				WriteLogTxt
				.Recording("點爆裝備紀錄","人物:" +"【"+ pc.getName() +"】"+ "點爆<裝備>" +"【" +"+"+item.getEnchantLevel() + item.getItem().getName() + "】"+" 物品OBJID:" + item.getId());
			}

