package com.lineage.data.item_etcitem.reel;

import java.util.Random;

import com.lineage.config.ConfigMagic_Special;
import com.lineage.data.cmd.EnchantArmor;
import com.lineage.data.cmd.EnchantExecutor;
import com.lineage.data.executor.ItemExecutor;
import com.lineage.server.model.L1ItemUpdata;
import com.lineage.server.model.Instance.L1ItemInstance;
import com.lineage.server.model.Instance.L1PcInstance;
import com.lineage.server.serverpackets.S_ServerMessage;
import com.lineage.server.serverpackets.S_SkillSound;
import com.lineage.server.templates.L1ItemAttr;

/**
 * <font color=#00800>飾品強化卷軸</font><BR>
 *
 */
public class ScrollEnchantAccessory extends ItemExecutor {

	/**
	 *
	 */
	private ScrollEnchantAccessory() {
		// TODO Auto-generated constructor stub
	}

	public static ItemExecutor get() {
		return new ScrollEnchantAccessory();
	}

	/**
	 * 道具物件執行
	 * @param data 參數
	 * @param pc 執行者
	 * @param item 物件
	 */
	@Override
	public void execute(final int[] data, final L1PcInstance pc, final L1ItemInstance item) {
		// 對象OBJID
		final int targObjId = data[0];

		// 目標物品
		final L1ItemInstance tgItem = pc.getInventory().getItem(targObjId);

		if (tgItem == null) {
			return;
		}
		final L1ItemAttr itemattr = tgItem.get_ItemAttrName2();//極品裝備同步安定值

		// 安定值
		int safe_enchant = tgItem.getItem().get_safeenchant();

		if (itemattr != null && itemattr.get_chant() >0){//極品裝備同步安定值
			safe_enchant += itemattr.get_chant();
		}

		boolean isErr = false;

		// 取得物件觸發事件
		final int use_type = tgItem.getItem().getUseType();
		switch (use_type) {
		case 23:// 戒指
		case 24:// 項鍊
		case 37:// 腰帶
		case 40:// 耳環
			if (tgItem.getItem().get_greater() == 3) {
				isErr = true;
			}
			if (safe_enchant < 0) { // 物品不可强化
				isErr = true;
			}
			break;

		default:
			isErr = true;
			break;
		}

		if (tgItem.getBless() >= 128) {// 封印的装備
			isErr = true;
		}

		if (isErr) {
			pc.sendPackets(new S_ServerMessage(79));// 没有任何事发生
			return;
		}

		// 物品已追加值
		final int enchant_level = tgItem.getEnchantLevel();

		// 限定所有 耳環 項鏈 戒指 腰帶 最高加到8
		if (enchant_level >= 8) {
			pc.sendPackets(new S_ServerMessage(79));// 没有任何事发生
			return;
		}

		final EnchantExecutor enchantExecutor = new EnchantArmor();
		int randomELevel = enchantExecutor.randomELevel(tgItem, item.getBless());
		pc.getInventory().removeItem(item, 1);

		boolean isEnchant = true;
		if (enchant_level < -6) {// 飾品将会消失,最大可追加到-7
			isEnchant = false;

		} else if (enchant_level < safe_enchant) {// 安定值內
			isEnchant = true;

		} else {// 超出安定值

			final Random random = new Random();
			final int rnd = random.nextInt(100) + 1;
			int enchant_chance_armor;
			int enchant_level_tmp;

			/*if (safe_enchant == 0) { // 對防具安定直為0初始計算+2
				enchant_level_tmp = enchant_level + 2;

			} else {
				enchant_level_tmp = enchant_level;
			}*/

			enchant_level_tmp = enchant_level;

			if (enchant_level >= 9) {
				enchant_chance_armor = (int) L1ItemUpdata.enchant_armor_up9(enchant_level_tmp);

			} else {
				enchant_chance_armor = (int) L1ItemUpdata.enchant_armor_dn9(enchant_level_tmp);
			}

			if (rnd < enchant_chance_armor) {
				isEnchant = true;

			} else if ((enchant_level >= 9) && (rnd < (enchant_chance_armor * 2))) {
				randomELevel = 0;

			} else {
				isEnchant = false;
			}
		}
		if ((randomELevel <= 0) && (enchant_level > -6)) {
			isEnchant = true;
		}

		if (isEnchant) {// 成功Charming
			enchantExecutor.successEnchant(pc, tgItem, randomELevel);
			//pc.sendPacketsX10(new S_SkillSound(pc.getId(), 17082));//強化成功
			//pc.sendPacketsX10(new S_SkillSound(pc.getId(), 17221));//強化成功
			if (ConfigMagic_Special.Broadcast_Charming_switch) {
			pc.sendPacketsX10(new S_SkillSound(pc.getId(), ConfigMagic_Special.Broadcast_Charming_GFX1));//強化成功
			pc.sendPacketsX10(new S_SkillSound(pc.getId(), ConfigMagic_Special.Broadcast_Charming_GFX2));//強化成功
			}
		} else {// 失敗
			enchantExecutor.failureEnchant(pc, tgItem);
			//pc.sendPacketsX10(new S_SkillSound(pc.getId(), 17136));//強化失敗
			if (ConfigMagic_Special.Broadcast_Charming_switch) {
			pc.sendPacketsX10(new S_SkillSound(pc.getId(), ConfigMagic_Special.Broadcast_Charming_failure_GFX));//強化失敗
		}
	}
}
}

methods.source:
protected int getMr() {
		int mr = _itemInstance.getItem().get_mdef();// DB設定抗魔
		Integer integer = MR.get(Integer.valueOf(_itemInstance.getItemId()));
		if (integer != null) {
			mr += _itemInstance.getEnchantLevel() * integer.intValue();
		}
		return mr;
	}

protected int getMpr() {
		int mpr = _itemInstance.getItem().get_addmpr();// DB設定回魔量
		Integer integer = MPR.get(Integer.valueOf(_itemInstance.getItemId()));
		if (integer != null) {
			mpr += _itemInstance.getEnchantLevel() * integer.intValue();
		}
		return mpr;
	}

protected int getSp() {
		int sp = _itemInstance.getItem().get_addsp();// DB設定SP
		Integer integer = SP.get(Integer.valueOf(_itemInstance.getItemId()));
		if (integer != null) {
			if (_itemInstance.getItemId() == 20107 || _itemInstance.getItemId() == 120107) {// 巫妖斗篷
				if (_itemInstance.getEnchantLevel() >= 3) {// 加3開始增加魔攻
					sp += (_itemInstance.getEnchantLevel() - 2) * integer.intValue();
				}
			} else if (_itemInstance.getItemId() == 21220 || _itemInstance.getItemId() == 121220) {// 幻象眼魔的心眼
				if (_itemInstance.getEnchantLevel() >= 8) {// 加8開始增加魔攻
					sp += (_itemInstance.getEnchantLevel() - 7) * integer.intValue();
				}
			} else if (_itemInstance.getItemId() == 21221 || _itemInstance.getItemId() == 121221) {// 馬昆斯斗篷
				if (_itemInstance.getEnchantLevel() >= 7) {// 加7開始增加魔攻
					sp += (_itemInstance.getEnchantLevel() - 6) * integer.intValue();
				}
			} else if (_itemInstance.getItemId() == 300431) {// 法師臂甲
				int enchantlvl = _itemInstance.getEnchantLevel();
				if (enchantlvl >= 5 && enchantlvl <= 6) {
					sp += integer.intValue();
				} else if (enchantlvl >= 7 && enchantlvl <= 8) {
					sp += integer.intValue() * 2;
				} else if (enchantlvl >= 9) {
					sp += integer.intValue() * 3;
				}
			} else {
				sp += _itemInstance.getEnchantLevel() * integer.intValue();
			}
		}
		return sp;
	}

protected int getDoubleDmgChance() {
		int x2 = _itemInstance.getItem().getDoubleDmgChance();// DB設定雙擊率
		Integer integer = X2.get(Integer.valueOf(_itemInstance.getItemId()));
		if (integer != null) {
			x2 += _itemInstance.getEnchantLevel() * integer.intValue();
		}
		return x2;
	}

protected int getHitModifierByArmor() {
		int hit = _itemInstance.getItem().getHitModifierByArmor();// DB設定命中率
		Integer integer = HIT.get(Integer.valueOf(_itemInstance.getItemId()));
		if (integer != null) {
			if (_itemInstance.getItemId() == 400051) {// 激怒手套
				if (_itemInstance.getEnchantLevel() >= 5) {// 加5開始增加命中率
					hit += (_itemInstance.getEnchantLevel() - 4) * integer.intValue();
				}
			} else {
				hit += _itemInstance.getEnchantLevel() * integer.intValue();
			}
		}
		return hit;
	}

protected int get_addhp() {
		int hp = _itemInstance.getItem().get_addhp();// DB設定增加血量
		Integer integer = HP.get(Integer.valueOf(_itemInstance.getItemId()));
		if (integer != null) {
			if (_itemInstance.getItemId() == 300429) {// 體力臂甲
				int enchantlvl = _itemInstance.getEnchantLevel();
				if (enchantlvl >= 5 && enchantlvl <= 6) {
					hp += integer.intValue();
				} else if (enchantlvl >= 7 && enchantlvl <= 8) {
					hp += integer.intValue() * 2;
				} else if (enchantlvl >= 9) {
					hp += integer.intValue() * 3;
				}
			} else {
				hp += _itemInstance.getEnchantLevel() * integer.intValue();
			}
		}
		return hp;
	}

protected int getDamageReduction() {
		int reduce = _itemInstance.getItem().getDamageReduction();// DB設定傷害減免
		Integer integer = DMG_REDUCE.get(Integer.valueOf(_itemInstance.getItemId()));
		if (integer != null) {
			if (_itemInstance.getItemId() == 300430) {// 守護的臂甲
				int enchantlvl = _itemInstance.getEnchantLevel();
				if (enchantlvl >= 5 && enchantlvl <= 6) {
					reduce += integer.intValue();
				} else if (enchantlvl >= 7 && enchantlvl <= 8) {
					reduce += integer.intValue() * 2;
				} else if (enchantlvl >= 9) {
					reduce += integer.intValue() * 3;
				}
			} else if (_itemInstance.getItemId() == 21223 || _itemInstance.getItemId() == 121223) {// 石製手套
				if (_itemInstance.getEnchantLevel() >= 7) {// 加7開始增加傷害減免
					reduce += (_itemInstance.getEnchantLevel() - 6) * integer.intValue();
				}
			} else {
				reduce += _itemInstance.getEnchantLevel() * integer.intValue();
			}
		}
		return reduce;
	}

protected int getPVPDmg() {
		int pvpdmg = _itemInstance.getItem().get_PVPdmg();// DB設定PVP額外傷害
		Integer integer = PVPDMG.get(Integer.valueOf(_itemInstance.getItemId()));
		if (integer != null) {
			if (_itemInstance.getItemId() >= 410207 && _itemInstance.getItemId() <= 410214) {// 火神武器

				int enchantlvl = _itemInstance.getEnchantLevel();// 武器強化值
				switch (enchantlvl) {
				case 8:
					pvpdmg += integer.intValue() * 2;
					break;
				case 9:
					pvpdmg += integer.intValue() * 3;
					break;
				case 10:
					pvpdmg += integer.intValue() * 4;
					break;
				case 11:
					pvpdmg += integer.intValue() * 5;
					break;
				case 12:
					pvpdmg += integer.intValue() * 6;
					break;
				}

				if (enchantlvl > 12) {
					pvpdmg += integer.intValue() * 6;
				}

			} else {// 其他武器
				pvpdmg += _itemInstance.getEnchantLevel() * integer.intValue();
			}
		}
		return pvpdmg;
	}

