		for (final ArmorSetEffect effect : _effects) {
			// 六屬性(力量,敏捷,體質,精神,魅力,智力)

			if (effect instanceof EffectStat_Str) {
				// 套裝效果:力量增加
				mode[0] = effect.get_mode();
			}

			if (effect instanceof EffectStat_Dex) {
				// 套裝效果:敏捷增加
				mode[1] = effect.get_mode();
			}

