	/**
	 * 固定傷害魔法武器
	 * @param pc
	 * @param cha
	 * @param weaponId
	 * @return
	 */
	public static double getWeaponSkillDamage(L1PcInstance pc, L1Character cha, int weaponId) {
		L1WeaponSkill weaponSkill = WeaponSkillTable.get().getTemplate(weaponId);
		if ((pc == null) || (cha == null) || (weaponSkill == null)) {
			return 0.0D;
		}

		int chance = _random.nextInt(100) + 1;
		if (weaponSkill.getProbability() < chance) {
			return 0.0D;
		}

		int skillId = weaponSkill.getSkillId();
		if (skillId != 0) {
			L1Skills skill = SkillsTable.get().getTemplate(skillId);
			if ((skill != null) && (skill.getTarget().equals("buff")) && (!isFreeze(cha))) {
				cha.setSkillEffect(skillId, weaponSkill.getSkillTime() * 1000);
			} else if (skillId == 4000) {
				cha.setSkillEffect(4000, weaponSkill.getSkillTime() * 1000);
				if ((cha instanceof L1PcInstance)) {
					L1PcInstance tgpc = (L1PcInstance) cha;
					tgpc.sendPackets(new S_Paralysis(6, true));
				} else if (((cha instanceof L1MonsterInstance)) || ((cha instanceof L1SummonInstance))
						|| ((cha instanceof L1PetInstance))) {
					L1NpcInstance tgnpc = (L1NpcInstance) cha;
					// tgnpc.setParalyzed(true);
					tgnpc.setPassispeed(0);
				}
			}
		}

		final int effectId = weaponSkill.getEffectId();
		// 具有動畫
		/*if (effectId > 0) {
			int chaId = 0;
			if (weaponSkill.getEffectTarget() == 0) {
				chaId = cha.getId();

			} else {
				chaId = pc.getId();
			}
			final boolean isArrowType = weaponSkill.isArrowType();
			if (!isArrowType) {
				pc.sendPacketsAll(new S_SkillSound(chaId, effectId));

			} else {
				final S_UseAttackSkill packet = new S_UseAttackSkill(
						pc, 
						cha.getId(),
						effectId, 
						cha.getX(), 
						cha.getY(),
						ActionCodes.ACTION_Attack, 
						false
						);
				pc.sendPacketsAll(packet);
			}
		}*/
		// 具有動畫
		if (effectId > 0) {
			int chaId = 0;
			if (weaponSkill.getEffectTarget() == 0) {
				chaId = cha.getId();

			} else {
				chaId = pc.getId();
			}
			final boolean isArrowType = weaponSkill.isArrowType();
			if (!isArrowType) {
				if (pc.is_send_weapon_gfxid()) {
					pc.sendPackets(new S_SkillSound(chaId, effectId));
				}
				pc.broadcastPacketForWeapon(new S_SkillSound(chaId, effectId));

			} else {
				final S_UseAttackSkill packet = new S_UseAttackSkill(pc, cha.getId(), effectId, cha.getX(),
						cha.getY(), ActionCodes.ACTION_Attack, false);
				if (pc.is_send_weapon_gfxid()) {
					pc.sendPackets(packet);
				}
				pc.broadcastPacketForWeapon(packet);
			}
		}
		double damage = 0;
		final int randomDamage = weaponSkill.getRandomDamage();
		if (randomDamage != 0) {
			damage = _random.nextInt(randomDamage);
		}
		damage += weaponSkill.getFixDamage();

		final int area = weaponSkill.getArea();
		if ((area > 0) || (area == -1)) { // 範圍技能
			for (final L1Object object : World.get().getVisibleObjects(cha, area)) {
				if (object == null) {
					continue;
				}
				if (!(object instanceof L1Character)) {
					continue;
				}
				if (object.getId() == pc.getId()) {
					continue;
				}
				if (object.getId() == cha.getId()) { // 攻撃対象はL1Attackで処理するため除外
					continue;
				}

				// 攻撃対象がMOBの場合は、範囲内のMOBにのみ当たる
				// 攻撃対象がPC,Summon,Petの場合は、範囲内のPC,Summon,Pet,MOBに当たる
				if (cha instanceof L1MonsterInstance) {
					if (!(object instanceof L1MonsterInstance)) {
						continue;
					}
				}
				if ((cha instanceof L1PcInstance)
						|| (cha instanceof L1SummonInstance)
						|| (cha instanceof L1PetInstance)) {
					if (!((object instanceof L1PcInstance)
							|| (object instanceof L1SummonInstance)
							|| (object instanceof L1PetInstance) 
							|| (object instanceof L1MonsterInstance))) {
						continue;
					}
				}

				damage = calcDamageReduction(pc, (L1Character) object, damage, weaponSkill.getAttr());
				if (damage <= 0) {
					continue;
				}
				if (object instanceof L1PcInstance) {
					final L1PcInstance targetPc = (L1PcInstance) object;
					// 受傷動作
					targetPc.sendPacketsAll(
							new S_DoActionGFX(
									targetPc.getId(), 
									ActionCodes.ACTION_Damage
									));
					targetPc.receiveDamage(pc, (int) damage, false, false);

				} else if ((object instanceof L1SummonInstance)
						|| (object instanceof L1PetInstance)
						|| (object instanceof L1MonsterInstance)) {
					final L1NpcInstance targetNpc = (L1NpcInstance) object;
					// 受傷動作
					targetNpc.broadcastPacketAll(
							new S_DoActionGFX(
									targetNpc.getId(), 
									ActionCodes.ACTION_Damage
									));
					targetNpc.receiveDamage(pc, (int) damage);
				}
			}
		}
		//修改weapon_skill table 增加顯示圖案
		if (weaponSkill.getGfxId() != 0) {
			if (weaponSkill.getGfxIdTarget()) {// 目標顯示
				pc.sendPacketsAll(new S_SkillSound(cha.getId(), weaponSkill
						.getGfxId()));
			} else {// 自己身上顯示
				pc.sendPacketsAll(new S_SkillSound(pc.getId(), weaponSkill
						.getGfxId()));
			}
		}
		//修改weapon_skill table 增加顯示圖案 gfxId2 by無語
		if (weaponSkill.getGfxId2() != 0) {
			if (weaponSkill.getGfxIdTarget2()) {// 目標顯示
				pc.sendPacketsAll(new S_SkillSound(cha.getId(), weaponSkill
						.getGfxId2()));
			} else {// 自己身上顯示
				pc.sendPacketsAll(new S_SkillSound(pc.getId(), weaponSkill
						.getGfxId2()));
			}
		}
		//修改weapon_skill table 增加顯示圖案 gfxId3 by無語
		if (weaponSkill.getGfxId3() != 0) {
			if (weaponSkill.getGfxIdTarget3()) {// 目標顯示
				pc.sendPacketsAll(new S_SkillSound(cha.getId(), weaponSkill
						.getGfxId3()));
			} else {// 自己身上顯示
				pc.sendPacketsAll(new S_SkillSound(pc.getId(), weaponSkill
						.getGfxId3()));
			}
		}
		//修改weapon_skill table 增加顯示圖案 gfxId4 by無語
		if (weaponSkill.getGfxId4() != 0) {
			if (weaponSkill.getGfxIdTarget4()) {// 目標顯示
				pc.sendPacketsAll(new S_SkillSound(cha.getId(), weaponSkill
						.getGfxId4()));
			} else {// 自己身上顯示
				pc.sendPacketsAll(new S_SkillSound(pc.getId(), weaponSkill
						.getGfxId4()));
			}
		}
		//修改weapon_skill table 增加顯示圖案 gfxId5 by無語
		if (weaponSkill.getGfxId5() != 0) {
			if (weaponSkill.getGfxIdTarget5()) {// 目標顯示
				pc.sendPacketsAll(new S_SkillSound(cha.getId(), weaponSkill
						.getGfxId5()));
			} else {// 自己身上顯示
				pc.sendPacketsAll(new S_SkillSound(pc.getId(), weaponSkill
						.getGfxId5()));
			}
		}						
		//~修改weapon_skill table 增加顯示圖案
		return calcDamageReduction(pc, cha, damage, weaponSkill.getAttr());

	}

	public static double getWeaponAttrOne(final L1PcInstance pc, final L1Character cha){
		double dmg = 0.0D;
		int gfx = 0;
		_weapon = pc.getWeapon();
		final L1ItemAttr itemattr = _weapon.get_ItemAttrName2();//極品裝備
		if (itemattr != null){
			if (cha instanceof L1PcInstance) {
				L1PcInstance pc1 = (L1PcInstance)cha;
				switch (itemattr.get_one()) {
				case 12:
					if (_random.nextInt(100) + 1 <= itemattr.get_one_rom()) {
						if (!pc1.hasSkillEffect(ERASE_MAGIC)) {
							pc1.setSkillEffect(ERASE_MAGIC, 32*1000);
							pc1.sendPackets(new S_SPMR(pc1));
						}
						gfx = itemattr.get_one_skill();
					}
					break;	

				case 13:
					if (_random.nextInt(100) + 1 <= itemattr.get_one_rom()) {
						if (pc1.hasSkillEffect(STATUS_FLOATING_EYE)) {
