	public static double getBaphometStaffDamage(L1PcInstance pc, L1Character cha) {
		double dmg = 0.0D;
		int chance = _random.nextInt(100) + 1;
		if (14 >= chance) {
			int locx = cha.getX();
			int locy = cha.getY();
			int sp = pc.getSp();
			int intel = pc.getInt();
			dmg = (intel + sp) * 1.8D + _random.nextInt(intel + sp) * 1.8D;
