	 * @param pc
	 * @param cha
	 * @param weaponId
	 * @return
	 */
	public static double getAreaSkillWeaponDamage(L1PcInstance pc, L1Character cha, int weaponId) {
		double dmg = 0.0D;
		int probability = 0;
		int attr = 0;
		int chance = _random.nextInt(100) + 1;
