		if (defenderDice <= 0) {
			defenderDice = 1;
		}

		hit_rnd = _hitRate * 100 / defenderDice;// 攻擊命中機率

		if (hit_rnd >= 100) {
			hit_rnd = 100;

		} else if (hit_rnd <= 0) {
			hit_rnd = 0;
