		case 18:// 鎖鏈劍
			weaponDamage = _random.nextInt(weaponMaxDamage) + 1;

			if ((_weaponId == 914) && (_pc.getLawful() < 500)) { // 惡夢的長弓，邪惡值越高
																	// 攻擊力越高
				int a = _pc.getLawful() / 3000;
				int b = Math.abs(a);
				weaponDamage += b;
			}
			break;
		}

		/*if (_pc.getClanid() != 0) {
			weaponDamage = (int) (weaponDamage + getDamageUpByClan(_pc));// 血盟技能增傷
		}*/
		if (_pc.getClanid() != 0) {
