public int calcPcDamage() {
		if (_targetPc == null) {
			return 0;
		}

		if (dmg0(_targetPc)) {
			_isHit = false;
			_drainHp = 0;
			return 0;
		}

		if (!_isHit) {
			return 0;
		}

		if (_targetPc.hasSkillEffect(COUNTER_BARRIER)) {
			L1MagicMode magic = new L1MagicPc(_targetPc, _pc);
			boolean isProbability = magic.calcProbabilityMagic(COUNTER_BARRIER);
			boolean isShortDistance = isShortDistance();

			if ((isProbability) && (isShortDistance) && (_weaponType2 != 17)) {
				commitCounterBarrier();
				_pc.sendPacketsAll(new S_SkillSound(_targetPc.getId(), 10710));
				return 0;
			}
		}

		if (_targetPc.isSkillMastery(TATIN_ROCK)
				&& (_targetPc.getCurrentHp() <= _targetPc.getMaxHp() / 100 * _targetPc.get_TatinHp())) {
			L1MagicMode magic = new L1MagicPc(_targetPc, _pc);
			boolean isProbability = magic.calcProbabilityMagic(TATIN_ROCK);
			boolean isShortDistance = isShortDistance();

			if ((isProbability) && (isShortDistance) && (_weaponType2 != 17)) {
				commitCounterBarrier();
				_pc.sendPacketsAll(new S_SkillSound(_targetPc.getId(), 12555));
				return 0;
			}
		}

		if (_targetPc.isSkillMastery(TATIN_BULLET)
				&& (_targetPc.getCurrentHp() <= _targetPc.getMaxHp() / 100 * _targetPc.get_TatinHp())) {
			L1MagicMode magic = new L1MagicPc(_targetPc, _pc);
			boolean isProbability = magic.calcProbabilityMagic(TATIN_BULLET);
			boolean isShortDistance = isShortDistance();

			if ((isProbability) && (!isShortDistance)) {
				commitCounterBarrier();
				_pc.sendPacketsAll(new S_SkillSound(_targetPc.getId(), 12557));
				return 0;
			}
		}

		if (_targetPc.isSkillMastery(TATIN_MAGIC)
				&& (_targetPc.getCurrentHp() <= _targetPc.getMaxHp() / 100 * _targetPc.get_TatinHp())) {
			L1MagicMode magic = new L1MagicPc(_targetPc, _pc);
			boolean isProbability = magic.calcProbabilityMagic(TATIN_MAGIC);

			if ((isProbability) && (_weaponType2 == 17)) {// 奇古獸
				commitCounterBarrier();
				_pc.sendPacketsAll(new S_SkillSound(_targetPc.getId(), 12559));
				return 0;
			}
		}

		/*
		 * int c3_power_type = c3_power(); if (c3_power() != 0) { return
		 * c3_power_to_pc(c3_power_type); }
		 */

		int weaponMaxDamage = _weaponSmall;

		_weaponDamage = weaponDamage1(weaponMaxDamage);// 武器亂數傷害計算

		//_weaponTotalDamage += weaponEffectLevelDamage(_weaponTotalDamage);

		if (_pc.hasSkillEffect(175)) {// 烈焰之魂 武器最大傷害值
			if (_weaponType != 20 && _weaponType != 62) {
				_weaponDamage = weaponMaxDamage;
			}
		}

		if (_weaponType == 20 || _weaponType == 62) {// 遠距離武器
			if (isDexCriticalDmg()) {
				_weaponDamage = weaponMaxDamage;// 武器最大傷害值
			}

		} else if (_weaponType2 == 17) {// 奇古獸
			if (isIntCriticalDmg()) {// 魔法爆擊
				_weaponDamage = weaponMaxDamage;// 武器最大傷害值
			}

		} /*else {// 近距離武器
			if (isStrCriticalDmg()) {
				_weaponDamage = weaponMaxDamage;// 武器最大傷害值
			}
		}*/
		else {// 近距離武器
			if (isStrCriticalDmg()) {
				_weaponDamage = weaponMaxDamage*2;// 武器最大傷害值
			} else if (_pc.hasSkillEffect(SOUL_OF_FLAME) && _weapon != null) {
				_weaponDamage = weaponMaxDamage;
				_weaponDamage = (int) (_weaponDamage * ConfigSkill.SOUL_OF_FLAME_DAMAGE);
			}
		}

		if (_pc.is_mazu()) {// 媽祖祝福武器傷害+5
			_weaponDamage += 5;
		}

		_weaponTotalDamage = _weaponDamage + _weaponAddDmg + _weaponEnchant;// 武器傷害
																			// +
																			// 武器額外點數
