private int calcNpcDamage() {
		Random random = new Random();

		if (_targetNpc == null) {
			return 0;
		}

		if (dmg0(_targetNpc)) {
			_isHit = false;
			_drainHp = 0;
			return 0;
		}

		if (!_isHit) {
			return 0;
		}

		if (_targetNpc.hasSkillEffect(COUNTER_BARRIER)) {
			L1MagicMode magic = new L1MagicNpc(_targetNpc, _pc);
			boolean isProbability = magic.calcProbabilityMagic(COUNTER_BARRIER);
			boolean isShortDistance = isShortDistance();

			if ((isProbability) && (isShortDistance) && (_weaponType2 != 17)) {
				commitCounterBarrier();
				_pc.sendPacketsAll(new S_SkillSound(_targetNpc.getId(), 10710));
				return 0;
			}
		}

		if (_targetNpc.hasSkillEffect(KIRTAS_BARRIER1)) {
			commitCounterBarrier();
			_pc.sendPacketsAll(new S_SkillSound(_targetNpc.getId(), 10710));
			return 0;
		}

