			if (isStrCriticalDmg()) {
				_weaponDamage = weaponMaxDamage;// 武器最大傷害值
			}
		}*/
		 else {// 近距離武器
				if (isStrCriticalDmg()) {
					_weaponDamage = weaponMaxDamage*2;// 武器最大傷害值
				} else if (_pc.hasSkillEffect(L1SkillId.SOUL_OF_FLAME) && _weapon != null) {
					_weaponDamage = weaponMaxDamage;
					_weaponDamage = (int) (_weaponDamage * ConfigSkill.SOUL_OF_FLAME_DAMAGE);
				}
			}

		if (_pc.is_mazu()) {// 媽祖祝福武器傷害+5
			_weaponDamage += 5;
		}

