		dmg *= Config_Occupational_injury.Other_To_isIllusionistandy;
        }

		if (_weapon != null) {
			final L1ItemAttr itemattr = _weapon.get_ItemAttrName2();//極品裝備
			if (itemattr != null) {
				if (_targetNpc.getNpcTemplate().is_boss() && itemattr.get_boss_dmg() != 0){
					dmg += itemattr.get_boss_dmg();
				}
				if (itemattr.get_dmg() != 0) {
					dmg += itemattr.get_dmg();
				}
			}
		}

		if (_targetNpc.hasSkillEffect(68)) {// 聖界減傷
			dmg /= 2.0D;
		}
		if (ConfigSkill.DOUBLE_BREAK_NO_WEAPON) {
			final int totalchance = _weaponDoubleDmgChance;
			if (_random.nextInt(100) < totalchance) {
				dmg *= ConfigSkill.DOUBLE_BREAK_DMG; 
			}
		}

		if (dmg <= 0.0D) {// 減免計算後傷害0以下
			_isHit = false;
			_drainHp = 0;
		}
		if (_pc.hasSkillEffect(Phantom_Fire)) {// 執行端擁有幻象炎玉魔法狀態效果
			if ((_random.nextInt(100) + 1) <= 50) {// 10%機率
				dmg += 10;// 額外造成傷害10
				_pc.sendPacketsX10(new S_SkillSound(_target.getId(),17031));//4781
			}
		}
		if (_pc.hasSkillEffect(Phantom_Wind)) {// 執行端擁有幻象風玉魔法狀態效果
			if ((_random.nextInt(100) + 1) <= 50) {// 10%機率
				// SKILL移轉
				final SkillMode mode = L1SkillMode.get().getSkill(SLOW);
				_target.broadcastPacketX8(new S_SkillSound(_target.getId(), 17030));//746
			}
		}

		if (_pc.hasSkillEffect(Phantom_Mine)) {// 執行端擁有幻象雷玉魔法狀態效果
			if ((_random.nextInt(100) + 1) <= 50) {// 10%機率
				final L1Magic magic = new L1Magic(_pc, _target);
				final int magic_dmg = magic.calcMagicDamage(CALL_LIGHTNING);
				magic.commit(magic_dmg, 0);
				final L1Skills skill = SkillsTable.get().getTemplate(CALL_LIGHTNING);
				final int castgfx = skill.getCastGfx();

				_target.broadcastPacketX8(new S_SkillSound(_target.getId(),
						castgfx));
			}
		}
		/**道具特化-物理傷害%數-發動機率*/
		if (_pc.getOtherDmgPercentByItem() > 0 && _pc.getOtherDmgRPercentByItem() > 0){
			if (_random.nextInt(100)+1 <= _pc.getOtherDmgRPercentByItem()){
				double i = _pc.getOtherDmgPercentByItem() / 100;
				dmg *= i;
			}
		}
		/**跟隨系統*/
		if(_pc.getBeFollowId() != 0) {
			_pc.setAttackId(_targetNpc.getId());
		}	

		return (int) dmg;
	}

private double weaponSkill(L1PcInstance pcInstance, L1Character character, double weaponTotalDamage) {
		double dmg = 0.0D;
		dmg = WeaponSkillStart.start_weapon_skill(pcInstance, character, _weapon, weaponTotalDamage);
		if (dmg != 0.0D) {
			return dmg;
		}

		switch (_weaponId) {
		case 124://舊版巴風特魔杖
			dmg = L1WeaponSkill.getBaphometStaffDamage(_pc, _target);
			break;
		case 204://深紅之弩
		case 86://20161201束縛術加入紅影
		case 100204://深紅之弩
			L1WeaponSkill.giveFettersEffect(_pc, _target);
			break;
		case 261://舊版大法師魔仗
			L1WeaponSkill.giveArkMageDiseaseEffect(_pc, _target);
			break;
		case 410131://天使魔杖
			L1WeaponSkill.giveTurn_Undead(_pc, _target);
			break;
		case 260://舊版狂風之斧
		case 263://舊版酷寒之矛
			dmg = L1WeaponSkill.getAreaSkillWeaponDamage(_pc, _target, _weaponId);
			break;
		case 264://舊版雷雨之劍
			dmg = L1WeaponSkill.getLightningEdgeDamage(_pc, _target);
			break;
		default:
			dmg = L1WeaponSkill.getWeaponSkillDamage(_pc, _target, _weaponId);
		}
		if (_weapon != null){	
			final L1ItemAttr itemattr = _weapon.get_ItemAttrName2();//極品裝備
			if (itemattr != null && itemattr.get_one_rom()!= 0){
				dmg += L1WeaponSkill.getWeaponAttrOne(_pc, _target);
			}

			if (itemattr != null && itemattr.get_two_rom()!= 0){
				dmg += L1WeaponSkill.getWeaponAttrTwo(_pc, _target);
			}

			if (itemattr != null && itemattr.get_three_rom()!= 0){
				dmg += L1WeaponSkill.getWeaponAttrThree(_pc, _target);
			}
		}
		return dmg;
	}

