			L1ItemInstance amulet = pc_inv.findItemId(amulets[i]);
			if (amulet != null && amulet.isEquipped()) {
				damage += 5;
				break;
			}
		}

		if (_pc.getWeapon() == null) {//沒有主武器則返回0
			return 0;
		}

		int resist = 0;
		switch (_calcType) {
		case PC_PC:
			switch (amulets.length) {
