				resist = _targetPc.getEarth();
				break;
			case 2:// 水靈守護之鍊
				resist = _targetPc.getWater();
				break;
			case 3:// 火靈守護之鍊
				resist = _targetPc.getFire();
				break;
			case 4:// 風靈守護之鍊
				resist = _targetPc.getWind();
				break;
			case 5:// 真 地靈守護之鍊
				resist = _targetPc.getEarth();
				break;
			case 6:// 真 水靈守護之鍊
				resist = _targetPc.getWater();
				break;
			case 7:// 真 火靈守護之鍊
				resist = _targetPc.getFire();
				break;
			case 8:// 真 風靈守護之鍊
				resist = _targetPc.getWind();
				break;
			}
			break;

		case PC_NPC:
			switch (amulets.length) {
			case 1:// 地靈守護之鍊
				resist = _targetNpc.getEarth();
				break;
			case 2:// 水靈守護之鍊
				resist = _targetNpc.getWater();
				break;
			case 3:// 火靈守護之鍊
				resist = _targetNpc.getFire();
				break;
			case 4:// 風靈守護之鍊
				resist = _targetNpc.getWind();
				break;
			case 5:// 真 地靈守護之鍊
				resist = _targetNpc.getEarth();
				break;
			case 6:// 真 水靈守護之鍊
				resist = _targetNpc.getWater();
				break;
			case 7:// 真 火靈守護之鍊
				resist = _targetNpc.getFire();
				break;
			case 8:// 真 風靈守護之鍊
				resist = _targetNpc.getWind();
				break;
			}
			break;
		}

		int resistFloor = (int) (0.16D * Math.abs(resist));

		if (resist < 0) {
			resistFloor *= -1;
		}

		double attrDeffence = resistFloor / 32.0D;
		double attrCoefficient = 1.0D - attrDeffence;

		damage = (int) (damage * attrCoefficient);

		return damage;
	}

