public void receiveDamage(final L1Character attacker, double damage, final int attr) {
		final int player_mr = getMr();
		final int rnd = _random.nextInt(300) + 1;
		if (player_mr >= rnd) {
			damage /= 2.0;
		}

		int resist = 0;
		switch (attr) {
		case L1Skills.ATTR_EARTH:
			resist = getEarth();
			break;

		case L1Skills.ATTR_FIRE:
			resist = getFire();
			break;

		case L1Skills.ATTR_WATER:
			resist = getWater();
			break;

		case L1Skills.ATTR_WIND:
			resist = getWind();
			break;
		}

		int resistFloor = (int) (0.32 * Math.abs(resist));
		if (resist >= 0) {
			resistFloor *= 1;

		} else {
			resistFloor *= -1;
		}

		final double attrDeffence = resistFloor / 32.0;

		final double coefficient = ((1.0 - attrDeffence) + (3.0 / 32.0));// 0.09375

		if (coefficient > 0) {
			damage *= coefficient;
		}
		this.receiveDamage(attacker, damage, false, false);
	}

public void receiveDamage(L1Character attacker, double damage, boolean isMagicDamage, boolean isCounterBarrier) {
		if (damage <= 0.0D) {// 傷害值0以下則返回
			return;
		}

		try {
			for (Integer key : this.getSkillEffect()) {
				Integer integer = (Integer) L1AttackList.SKM0.get(key);
				if (integer != null) {
					return;
				}
			}
		} catch (ConcurrentModificationException localConcurrentModificationException) {
		} catch (Exception e) {
			_log.error(e.getLocalizedMessage(), e);
			return;
		}

		if ((getCurrentHp() > 0) && (!isDead())) {
			if (attacker != null) {
				if ((attacker != this) && (!(attacker instanceof L1EffectInstance)) && (!knownsObject(attacker))
						&& (attacker.getMapId() == getMapId())) {
					attacker.onPerceive(this);
				}

				if (isMagicDamage) {// 魔法傷害遞減
					damage = isMagicDamager(damage);
				}

				L1PcInstance attackPc = null;
				L1NpcInstance attackNpc = null;

				if ((attacker instanceof L1PcInstance)) {// 攻擊者是PC
					attackPc = (L1PcInstance) attacker;

					if (attackPc.getId() == L1PcInstance.this.getId()) {// 攻擊者是自己
						return;
					}
					if (IsAuto() && IsAttackTeleport()){
						setIsAttackTeleportHp(true);
					}
				} else if ((attacker instanceof L1NpcInstance)) {// 攻擊者是NPC
					attackNpc = (L1NpcInstance) attacker;
				}

				/*if ((attacker instanceof L1PcInstance)) {
					attackPc = (L1PcInstance) attacker;
					if (IsAuto() && IsAttackTeleport()){
						setIsAttackTeleportHp(true);
					}
				} else if ((attacker instanceof L1NpcInstance)) {
					attackNpc = (L1NpcInstance) attacker;
				}*/

				if (damage > 0.0D) {// 受到傷害大於0
					delInvis();
					removeSkillEffect(66);
					removeSkillEffect(212);

					if (attackPc != null) {
						L1PinkName.onAction(this, attackPc);
						if (attackPc.isPinkName()) {
							for (L1Object object : World.get().getVisibleObjects(attacker)) {
								if ((object instanceof L1GuardInstance)) {
									L1GuardInstance guard = (L1GuardInstance) object;
									guard.setTarget((L1PcInstance) attacker);
								}
							}
						}
					}
				}

				// 攻擊者被施放疼痛的歡愉
				if(attacker.hasSkillEffect(JOY_OF_PAIN) 
						&& getId() != attacker.getId()){

					int nowDamage = (getMaxHp() - getCurrentHp());
					nowDamage /=  ConfigIllusionstSkill.JOY_OF_PAIN_COUNTDMG;
					if (nowDamage > 0) {
						//限制疼痛歡愉最大傷害
						if ((nowDamage) > ConfigIllusionstSkill.JOY_OF_PAIN_DMG){
							nowDamage = ConfigIllusionstSkill.JOY_OF_PAIN_DMG;
						}

						if (attacker instanceof L1PcInstance) {
							attackPc = ((L1PcInstance) attacker);
							attackPc.sendPackets(new S_DoActionGFX(attackPc
									.getId(), ActionCodes.ACTION_Damage));
							attackPc.broadcastPacketAll(new S_DoActionGFX(attackPc
									.getId(), ActionCodes.ACTION_Damage));
							int Joy_Hp = attackPc.getCurrentHp() - nowDamage;
							if (Joy_Hp <= 0) {
								if (!attackPc.isGm()) {
									attackPc.setCurrentHp(1);
								} else {
									attackPc.setCurrentHp(attackPc.getMaxHp());
								}
							} else {
								attackPc.setCurrentHp(Joy_Hp);
							}
							//attackPc.receiveDamage(this, nowDamage ,false , true);
							attackPc.removeSkillEffect(JOY_OF_PAIN);//限定反彈一次傷害
						} else if (attacker instanceof L1MonsterInstance) {
							attackNpc = (L1MonsterInstance) attacker;
							attackNpc.receiveDamage(this, (int) (nowDamage));
							attackNpc.broadcastPacketAll(new S_DoActionGFX(attackNpc
									.getId(), ActionCodes.ACTION_Damage));
							attackNpc.removeSkillEffect(JOY_OF_PAIN);//限定反彈一次傷害
						}
					}
				}

				if (!isCounterBarrier) {// 執行傷害反彈
					if ((this.hasSkillEffect(191)) && (this.getId() != attacker.getId())) {// 致命身軀反彈
						if (_random.nextInt(100) < 23) {// 23%機率觸發
							int dmg = 40;
							if (attackPc != null) {
								if (attackPc.hasSkillEffect(68)) {// 聖界減傷
									dmg /= 2;
								}
								attackPc.sendPacketsAll(new S_DoActionGFX(attackPc.getId(), 2));
								this.sendPacketsAll(new S_SkillSound(this.getId(), 10710));
								attackPc.receiveDamage(this, dmg, false, true);
								return;

							} else if (attackNpc != null) {
								if (attackNpc.hasSkillEffect(68)) {// 聖界減傷
									dmg /= 2;
								}
								attackNpc.broadcastPacketAll(new S_DoActionGFX(attackNpc.getId(), 2));
								this.sendPacketsAll(new S_SkillSound(this.getId(), 10710));
								attackNpc.receiveDamage(this, dmg);
								return;
							}
						}
					}

					if ((!isMagicDamage) && (_elitePlateMail_Valakas > 0)) { // 巴拉卡斯的弓箭反屏
						int nowDamage = _random.nextInt(_valakas_dmgmax - _valakas_dmgmin + 1) + _valakas_dmgmin;
						if ((attackPc != null) && (_random.nextInt(1000) < _elitePlateMail_Valakas)) {
							L1ItemInstance weapon = attackPc.getWeapon();
							L1AttackMode attack = new L1AttackPc(attackPc, this);
							boolean isShortDistance = attack.isShortDistance();
							if ((weapon != null) && (!isShortDistance)) {
								if (attackPc.hasSkillEffect(68)) {// 聖界減傷
									nowDamage /= 2;
								}
								this.sendPacketsAll(new S_SkillSound(getId(), 10419));
								attackPc.sendPacketsAll(new S_DoActionGFX(attackPc.getId(), 2));
								attackPc.receiveDamage(this, nowDamage, false, true);
								return;
							}

						} else if ((attackNpc != null) && (_random.nextInt(1000) < _elitePlateMail_Valakas)) {
							L1AttackMode attack = new L1AttackNpc(attackNpc, this);
							boolean isShortDistance = attack.isShortDistance();
							if (!isShortDistance) {
								if (attackNpc.hasSkillEffect(68)) {// 聖界減傷
									nowDamage /= 2;
								}
								this.sendPacketsAll(new S_SkillSound(getId(), 10419));
								attackNpc.broadcastPacketAll(new S_DoActionGFX(attackNpc.getId(), 2));
								attackNpc.receiveDamage(this, nowDamage);
								return;
							}
						}
					}

					// 黑帝斯斗篷反彈傷害
					if (_hades_cloak > 0) {
						int nowDamage = _random.nextInt(_hades_cloak_dmgmax - _hades_cloak_dmgmin + 1)
								+ _hades_cloak_dmgmin;
						if ((attackPc != null) && (_random.nextInt(1000) < _hades_cloak)) {
							if (attackPc.hasSkillEffect(68)) {// 聖界減傷
								nowDamage /= 2;
							}
							attackPc.sendPacketsAll(new S_DoActionGFX(attackPc.getId(), 2));
							this.sendPacketsAll(new S_SkillSound(this.getId(), 10710));
							attackPc.receiveDamage(this, nowDamage, false, true);
							return;

						} else if ((attackNpc != null) && (_random.nextInt(1000) < _hades_cloak)) {
							if (attackNpc.hasSkillEffect(68)) {// 聖界減傷
								nowDamage /= 2;
							}
							attackNpc.broadcastPacketAll(new S_DoActionGFX(attackNpc.getId(), 2));
							this.sendPacketsAll(new S_SkillSound(this.getId(), 10710));
							attackNpc.receiveDamage(this, nowDamage);
							return;
						}
					}

					if (this.has_powerid(6612)) {// 附魔系統 還擊傷害
						int rad = 15;// 機率
						int dmg = 80;// 反彈傷害值
						if ((attackPc != null) && (_random.nextInt(100) < rad)) {
							if (attackPc.hasSkillEffect(68)) {// 聖界減傷
								dmg /= 2;
							}
							attackPc.sendPacketsAll(new S_DoActionGFX(attackPc.getId(), 2));
							this.sendPacketsAll(new S_SkillSound(this.getId(), 10710));
							attackPc.receiveDamage(this, dmg, false, true);
							return;

						} else if ((attackNpc != null) && (_random.nextInt(100) < rad)) {
							if (attackNpc.hasSkillEffect(68)) {// 聖界減傷
								dmg /= 2;
							}
							attackNpc.broadcastPacketAll(new S_DoActionGFX(attackNpc.getId(), 2));
							this.sendPacketsAll(new S_SkillSound(this.getId(), 10710));
							attackNpc.receiveDamage(this, dmg);
							return;
						}
					}
				}
			}

			if (this.hasSkillEffect(219)) {// 化身
				damage *= 1.05D;
			}

			int addmp = 0;
			if ((_elitePlateMail_Lindvior > 0) && // 林德拜爾的魔力守護
					(_random.nextInt(1000) < _elitePlateMail_Lindvior)) {
				sendPacketsAll(new S_SkillSound(getId(), 2188));
				addmp = _random.nextInt(_lindvior_mpmax - _lindvior_mpmin + 1) + _lindvior_mpmin;
				int newMp = getCurrentMp() + addmp;
				setCurrentMp(newMp);
			}

			int addhp = 0;
			if ((_elitePlateMail_Fafurion > 0) && // 法利昂的治癒守護
					(_random.nextInt(1000) < _elitePlateMail_Fafurion)) {
				sendPacketsAll(new S_SkillSound(getId(), 2187));
				addhp = _random.nextInt(_fafurion_hpmax - _fafurion_hpmin + 1) + _fafurion_hpmin;
			}

			if ((_Hexagram_Magic_Rune > 0) && // 六芒星的淨化
					(_random.nextInt(1000) < _Hexagram_Magic_Rune)) {
				sendPacketsAll(new S_SkillSound(getId(), _hexagram_gfx));
				addhp = _random.nextInt(_hexagram_hpmax - _hexagram_hpmin + 1) + _hexagram_hpmin;
			}

			if ((_dimiter_bless > 0) && // 蒂蜜特的祝福
					(_random.nextInt(1000) < _dimiter_bless)) {
				if (!this.hasSkillEffect(IMMUNE_TO_HARM)) {// 身上沒有聖界效果
					sendPacketsAll(new S_SkillSound(getId(), 11101));
					setSkillEffect(IMMUNE_TO_HARM, _dimiter_time * 1000);
					sendPackets(new S_PacketBox(S_PacketBox.ICON_I2H, _dimiter_time));
				}
			}

			if ((_dimiter_mpr_rnd > 0) && // 蒂蜜特的魔力回復
					(_random.nextInt(1000) < _dimiter_mpr_rnd)) {
				sendPacketsAll(new S_SkillSound(getId(), 2188));
				addmp = _random.nextInt(_dimiter_mpmax - _dimiter_mpmin + 1) + _dimiter_mpmin;
				int newMp = getCurrentMp() + addmp;
				setCurrentMp(newMp);
			}

			if ((_dimiter_blessA > 0) && // 蒂蜜特的祝福
					(_random.nextInt(1000) < _dimiter_blessA)) {
				if (!this.hasSkillEffect(IMMUNE_TO_HARM)) {// 身上沒有聖界效果
					if (_dimiter_gfxA > 0){
						sendPacketsAll(new S_SkillSound(getId(), _dimiter_gfxA));
					}
					sendPacketsAll(new S_SkillSound(getId(), 11101));
					setSkillEffect(IMMUNE_TO_HARM, _dimiter_timeA * 1000);
					sendPackets(new S_PacketBox(S_PacketBox.ICON_I2H, _dimiter_timeA));
				}
			}

			if ((_dimiter_mpr_rndA > 0) && // 蒂蜜特的魔力回復
					(_random.nextInt(1000) < _dimiter_mpr_rndA)) {
				if (_dimiter_gfxA > 0){
					sendPacketsAll(new S_SkillSound(getId(), _dimiter_gfxA));
				}
				sendPacketsAll(new S_SkillSound(getId(), 2188));
				int c = _dimiter_mpmaxA - _dimiter_mpminA;
				int cc = _random.nextInt(c)+1;
				addhp = cc + _dimiter_mpminA;
				int newHp = getCurrentHp() + addhp;
				setCurrentHp(newHp);
				System.out.println("被敵人攻擊回血 : " + addhp + " 滴");
			}

			int newHp = getCurrentHp() - (int) damage + addhp;
			if (newHp > getMaxHp()) {
				newHp = getMaxHp();
			}

			if ((newHp <= 0) && (!isGm())) {
				death(attacker);
			}

			this.setCurrentHp(newHp);// 目前HP變更處理

		} else if (!isDead()) {
			_log.error("人物hp減少處理失敗 可能原因: 初始hp為0");
			death(attacker);
		}
	}

