		} catch (final SQLException e) {
			_log.error(e.getLocalizedMessage(), e);

		} finally {
			SQLUtil.close(rs);
			SQLUtil.close(pstm);
			SQLUtil.close(con);
		}
		_log.info("讀取->[武器附魔(Boss)]資料數量: " + _magicList.size() + "(" + timer.get() + "ms)");
	}

public final L1MagicBossWeapon get(final int id,final int steps) {
		final int index = id * 100 + steps;
		return _magicList.get(index);
	}

